def P(t, style='body'):
    return Paragraph(html.escape(str(t)).replace('\n','<br/>'), styles[style])
def rich(t,style='body'): return Paragraph(t,styles[style])
def h(t): return P(t,'h1')
def sub(t): return P(t,'h2')
def paras(*items): return [P(x) for x in items]
def title(t,notice=True): return [P(t,'title')]+([P(NOTICE,'small')] if notice else [])
def tbl(rows,widths=None):
    cells=[[P(v,'table') for v in row] for row in rows]
    t=Table(cells,colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),PAPER),('LINEBELOW',(0,0),(-1,0),.7,INK),('LINEBELOW',(0,1),(-1,-1),.25,colors.HexColor('#C7BDAA')),('VALIGN',(0,0),(-1,-1),'TOP'),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7)]))
    return t
def foot(c,doc):
    c.setAuthor(''); c.setCreator('PDF document generator'); c.setSubject('作品审核材料')
    c.setStrokeColor(RED); c.setLineWidth(1); c.line(42,804,553,804)
    c.setFont(FONT,8); c.setFillColor(INK); c.drawString(42,819,'八十八个地名 / 审核材料')
    c.drawString(42,25,'2026-10-22 | AI生成审核版，需团队改定')
    c.drawRightString(553,25,str(doc.page))
manifest=[]
def save(rel,story,max_pages=None):
    path=OUT/rel; path.parent.mkdir(parents=True,exist_ok=True)
    doc=SimpleDocTemplate(str(path),pagesize=(595.276,841.89),leftMargin=42,rightMargin=42,topMargin=50,bottomMargin=44,title=path.stem,author='')
    doc.build(story,onFirstPage=foot,onLaterPages=foot)
    reader=PdfReader(path)
    pages=len(reader.pages)
    assert not max_pages or pages<=max_pages,(path,pages,max_pages)
    assert not reader.metadata.author,(path,reader.metadata.author)
    assert all((p.extract_text() or '').strip() for p in reader.pages)
    manifest.append({'path':str(path.relative_to(OUT)),'pages':pages,'bytes':path.stat().st_size,'selectable_text':True,'author_empty':True})
    print(path.name,pages,path.stat().st_size)

def qa_summary():
    if not qa: return '浏览器验收结果尚未写入本次生成器。以交付包工作记录中的最新 QA 报告为准；不能据此认定浏览器全项通过。'
    if isinstance(qa,dict) and qa.get('documentSummary'): return str(qa['documentSummary'])
    results=qa.get('results',[])+extra.get('results',[])
    passed=sum(1 for r in results if r.get('passed') is True)
    failed=sum(1 for r in results if r.get('passed') is False)
    return '本轮浏览器自动化共'+str(len(results))+'项，其中'+str(passed)+'项通过、'+str(failed)+'项未通过。包括Chrome/Edge在中文空格路径中以file://离线走通九段，以及触屏仿真六交互和海报下载。记录见工作记录/qa-report.json与acceptance-extra.json。由AI代理执行，不等同于学生人工多机实测、手机实机或用户测试；真人旁白未录制。'

