script=title('创作脚本与视觉声音规范')+paras('本稿为AI创作审核稿，未举行团队读稿会，未形成团队定稿。标签使用“史实·S编号”“引用·S编号”“AI创作文案”“艺术示意”；仅在学生实际改写并留痕后才可改为“团队创作”。','九段目标总时长440秒（7分20秒）。旁白共'+str(sum(len(x['narration']) for x in content['scenes']))+'字（含标点），各幕均不超过90字。旁白目标不是全程填满，保留操作和阅读时间。')
