script += [PageBreak(),h('关键句备选 / 每项三句')]
alternatives={
'序幕第一句':['我们从一根竹竿开始读这段路。','先看一根竹竿，再慢慢读出它留下的地名。','一件随人赶路的物品，把我们带到支前路上。'],
'第四幕证据边界':['报道列举的名称到这里留下省略，我们继续查证。','这一页写下的是选定名称，完整清单仍需更多证据。','我们把已经找到的读清，也把尚待核对的说明白。'],
'第五幕收束':['数字之外，是许多普通人共同托起的胜利。','把这些人次记在一起，也记住每一份具体的付出。','一路接续的运输和救护，让共同用力有了可见的形状。'],
'第七幕海报引导':['写下你所在的地名，留一句今天的致敬。','从你生活的地方，寄出一份记住这段路的心意。','把今天的地名写在海报上，带走一次认真阅读的记忆。'],
'尾声最后一句':['愿那些为共同生活付出的人，被认真记住。','这一次阅读到这里，继续查证与记住的路仍在前面。','我们留下出处，也留下愿意继续理解的心意。']}
for k,vals in alternatives.items(): script += [sub(k)]+paras(*[str(i+1)+'. [AI创作文案] '+v for i,v in enumerate(vals)])
script += [sub('海报致敬语 / 六个候选')]+paras(*[str(i+1)+'. [AI创作文案] '+v for i,v in enumerate(content['posterMessages']+['每个平凡的脚步，都值得记住。','记住这段路，也记住同行的人。','让今天的生活，回应昨天的付出。'])])
script += [PageBreak(),h('视觉规范')]+paras('色板：墨黑#1C1A17、纸白#EFE6D2、朱红#B3261E。朱红仅用于关键地名、进度与按钮，不作大面积背景。图像采用粗刀刻线和纸张纹理，不临摹具体木刻作品。','字体：网页正文思源宋体，地名／手写感文字霞鹜文楷，OFL许可随附；PDF统一霞鹜文楷。桌面正文≥18px、字幕≥20px、角标≥12px；手机正文≥16px。字号以实测无遮挡为验收条件。','1920×1080：左右安全边距约64px，顶部工具区56px以上，底部导航72px左右；图像位于右半区域，文案与交互留出分离空间。390×844：边距16–20px，单列排布，导航允许内部滚动；主按钮触控区≥44px。','竹竿导航：未到为浅墨、已到朱红、当前加形状或下划线以免只靠颜色。史料卡：浅纸底、墨字、链接朱红，支持键盘关闭。按钮：默认细框、悬停加深、焦点2px轮廓、禁用降低饱和并说明原因。字幕条不遮挡主操作。','标签固定为“史实·S编号”“艺术示意·AI辅助生成”“AI辅助文案／代码”。“团队实拍／录音／创作”只可在完成并有证据后使用。减少动效时取消位移与闪动，仍完整显示543点。')
script += [h('素材清单')]
rows=[['编号／类型','文件与规格','用途／负责人／验收']]
for i,img in enumerate(art['images']): rows.append(['A0'+str(i+1)+' AI图',img['name']+'.webp\n1672×941；'+str(img['bytes'])+'字节','全片按内容复用；AI代理生成，成员C待审。无文字、人脸、旗徽；<400KB；XMP已写入。'])
rows += [['G01 代码绘制','竹竿、节点、小车、手、543点、海报','AI代码；成员B待审。交互及数字准确，海报1080×1920。'],['P01 团队实拍（未制作）','竹竿教学道具正面/侧光照片4张及10秒片段2条','成员D。标“教学道具示意”；不造档案，不复刻无法核实的残损。'],['V01–V09 真人旁白（未录）','vo_s0.mp3 至 vo_s8.mp3；44.1/48kHz；128kbps','成员D。清楚无爆音、不含个人信息；总音频≤20MB。'],['F01 拟音（未录）','针划、脚步、木轮各2条；10–20秒WAV母版','成员D。安静环境、无音乐侵权、可循环无突变。'],['M01 音乐（未采用）','如后续使用，必须另列授权','成员D。无授权不加入；当前版本无背景音乐素材。']]
