tasks=[('竹竿教学道具 / 1.5小时','成员D；竹竿、铅笔及安全刻写工具。只刻已核验的10个选定名称；未证实的78个位置留白，不伪造不可辨刻痕。名称顺序仅为展示排版，显式标教学示意，不暗示原件尺寸与字位。'),('侧光拍摄 / 1小时','手机、台灯、素色纸；拍正面2张、侧光2张、横向移动10秒视频2条。固定机位和曝光，避免反光、实名物件和第三人正脸。去除GPS与设备个人信息。'),('旁白录制 / 2小时','成员D先与成员E改定脚本；安静房间、手机距口15–20cm稍偏轴。每幕2遍，保留干声母版，峰值避免削波；没有仿声。听完后逐句对应字幕，目标误差<0.5秒。'),('拟音与剪辑 / 1.5小时','针划竹面、土路脚步、木轮或木料摩擦，各录10–20秒2遍；标明实际声源，不冒称历史录音。剪去爆音，循环首尾平滑；音乐未授权不使用。'),('后期与留痕 / 2小时','成员C审核手形、器械结构、色调；只对确有需要之处修改，保存原图与修改图、真实操作时间及理由。成员B替换资源后回归全部交互，重新导出截图、视频与AI说明。')]
for a,b in tasks: script += [sub(a),P(b)]
script += [h('声音层级与退出规则')]+paras('真人音轨加入后：旁白为基准；环境声比旁白低约15–20dB，音乐低约12–18dB，拟音短促不过旁白。以上是制作起点，最终以听感和波形复核。第3幕协力通过可首次引入已获许可的音乐；第5幕略展开，第6幕退出留白。当前无音乐、无真人音轨。','切幕即停止上幕音频并清理定时器；静音影响全部声音；开始前不自动播放。每段字幕按实际录音时间码调整，不按固定阅读速度假定同步。')
save('八十八个地名_交付包/05_补充成果材料/创作脚本与视觉声音规范.pdf',script)

# 每阶段四项，真实区分代理检查与人工。
stages=[
('1 史料初核','事实底本、禁用说法、人工核验清单；S01–S12。','来源有机构、日期、URL、短引文及边界；S10/S11未作为主文依据。','成员A逐条打开截图；联系馆方核清原件、范围；未完成前保留审核版。','AI检索与摘要；没有伪造团队截图或完整88地名。'),
('2 脚本','9段440秒脚本；5组各3句备选；6句海报候选。','旁白总量≤750字、单幕≤90字；史实与创作分层；真实人物无虚构对白。','成员E读稿、亲手改写与留痕；真人录音后口语复核。','AI依据来源撰写审核稿；没有团队定稿会议记录。'),
('3 分镜与规范','每幕两画面、色板与组件、素材表、声音与拍录任务单。','不使用真实面孔、旗徽、伪地图和伪档案；计划素材标明未制作。','成员C/D确认可做范围并按任务单采集；留原始文件。','AI制定制作建议，未代做团队实拍／录音。'),
('4 图像','4张原始PNG与WebP；完整Prompt、编码记录和XMP。','每张<400KB；已AI视觉检查，统一暖纸黑墨；未宣称2K原生。','成员C逐张审核并做有必要的人工后期，记录实际变化。','内置image_gen每图一次；仅格式转换压缩，不虚构人工后期。'),
('5 代码','离线网页及分离内容、来源、素材模块。','实现状态与最终文件、QA报告对应；非module，不依赖线上内容加载。','成员B双击运行Chrome/Edge；测试中文空格路径及下载。','AI生成代码和集成；学生贡献尚无已确认记录。'),
('6 集成测试','84项机器QA记录、真实运行截图、约3分钟原速快览和4:40字幕审核演示视频。','84项机器检查通过；两支1080p视频均无音轨，不把自动化当用户研究。','5–8人体验、第二台电脑、真人字幕同步；实际问题回传修复。','AI代理自动化检查、修复与录屏，不编造测试人数及反馈。'),
('7 材料','介绍、运行、来源、AI八部分说明、视频脚本、PPT逐页内容。','介绍≤6页、运行1页；PDF作者空；填报稿未写成已提交。','成员E改定文字；成员D真人解说；成员A填实名报名并盖章。','AI制作审核材料与机器录屏；无身份审核代填。'),
('8 终检','技术项及评分维度检查、接手手册。','所有未具备证据项目标需人工；不能认定可直接正式参赛。','最后核对官网与系统、上传、点击提交审核并保存作品编号。','AI整理交付；未登录报名系统、未盖章、未点击提交。')]
