hand=title('团队接手手册',False)+paras(NOTICE,'本次交付是可运行、可审核、可继续制作的成果包。84项浏览器自动化检查已通过；已交付约3分钟原速快览和4:40字幕审核视频，均为1080p、无音轨。正式参赛仍需学生真实工作及其证据、史料人审、真人解说与报名盖章。')
hand += [h('先做什么')]
for a,b in [('先联系学校 / 现在','确认校内截止、承诺书系统生成与盖章办理；国家截止提醒为2026-10-23 23:59:59（北京时间）。不得把最后上传留到最后几分钟。'),('史料核验 / 优先','按清单先核S01/S02/S03/S04，关注10/88、收藏地与人次；截图并记录真实日期。无法证实的删除，勿补写猜测。'),('真实创作 / 优先','亲自改定旁白、审核图像，录制本人解说；有时间按任务单做竹竿教学道具与拟音。保留原稿/修改稿、原图/修改图，不补造过去会议。'),('实机验收 / 必须','在Chrome和Edge从解压路径走通；换一台无开发环境电脑；断网、跳过、静音、海报下载、手机视口；真人音轨加入后再测字幕。'),('材料改定 / 必须','更新介绍与AI八部分说明：谁实际做了什么、证据在哪里。系统填报文本与视频脚本为草稿。评审视频真人解说尚未录制时不要称已完成。'),('上传与确认 / 必须','截图不超过10张，视频/PPT按系统栏目单独传；作品及适用PDF放ZIP。上传后点击提交审核，保存“提交成功”、作品编号和时间截图。')]: hand += [sub(a),P(b)]
hand += [PageBreak(),h('文件、编辑与回归')]+paras('网页入口：01_作品及成果文件/八十八个地名/index.html。改文字用js/content.js；改来源用js/sources.js；更换素材同步js/assets.js与AI说明。所有路径保持相对，网页不需要安装。','视频：交付包02_作品展示视频/作品快览_实际运行_无配音.mp4；单独上传/作品演示视频_审核版.mp4。后者4分40秒含说明字幕，尚无真人解说；真人录音后重剪并核对字幕。','内容与来源编辑源在交付包工作记录/content.json、sources.json。文档生成脚本在工作区tools/build_documents.py；由维护者运行后重导PDF并渲染检查。修改史实必须先改底本，再同步网页和文档，避免不同版本矛盾。','原始图像与生成Prompt属于AI过程证据；提交版文档不含本机路径。工作记录中的真实生成和测试记录不能改成成员会议、人工核验或用户反馈。','机器检查明细见qa-report.json（28项）和acceptance-extra.json（56项）；T10真人配音同步、T21第二台真实电脑仍未完成。若仅凭人工观察发现问题，记录设备、浏览器、场景、动作、期望与实际。不要为了赶时间删除真实问题记录。')
hand += [sub('匿名化清单')]+paras('专家评审文件不得出现学校、成员/教师姓名、账号、桌面通知、浏览器头像、手机号、EXIF位置、PDF作者。报名信息和承诺书是身份审核材料，应真实填写，不能为了匿名把必要实名字段删空。','发布前再搜索文件名、页面、海报、PDF属性和视频画面；网页自动化录屏使用匿名窗口。若更换实拍图，重新检查EXIF。')
hand += [sub('不用补造的记录')]+paras('未进行的会议，不补写过去日期；未测试的同学，不填5–8个人名；未人工后期，不写修形调色；未现场拍摄，不把AI图叫实拍；未真人录音，不用声音克隆代替；未上传，不写提交成功。真实做完一项再记一项。')
save('团队接手手册.pdf',hand)

# 独立上传文字：无承诺书、无伪造身份，明确草稿。
intro200='《八十八个地名》是一部离线交互网页，以唐和恩的支前竹竿为线索，通过刻、推、一起推、读、数、留六个动作，连接文物叙事、人民支前与当代致敬。本作选用权威报道列举的10个名称，明确其并非完整路线；史实可查看S编号和出处。九段脚本目标约7分20秒，可本地生成致敬海报。当前为AI生成审核版，图像有AI标识；团队人工核验、实拍、真人配音、后期与用户测试尚未完成。'
intro500=intro200+'\n作品面向大学生、中学生和红色研学参观者，拟用于课堂导入与纪念场馆延伸阅读。界面以竹竿式导航贯穿，各幕有继续、跳过、字幕、史料与说明入口；通过543个光点呈现543万人次，每点表示1万人次，不对应独立个人名单。选定地名按报道列举展开，标注“路线示意，非地图”；“第八十九个地名”是当代致敬创作，不增补历史文物。\n工程采用本地HTML、CSS和JavaScript，内容、来源与素材配置分离，不调用在线接口。图像为四张木刻艺术示意，没有真人历史面孔、仿声或伪档案。来源底本保留机构、日期、短引文与争议，原件收藏地等未决问题不作确定结论。\n本轮文案、图像、代码、文档及自动化测试由AI代理完成。学生真实改写、录制、实测和定稿需完成后据实更新，尚无教学成效或用户反馈数据。'
systemtxt='系统填报文案 / AI审核稿，团队改定后再复制\n\n作品名称：'+TITLE+'\n赛道/赛项：指定命题“红色之旅 追梦铸魂”作品赛项，以系统实际栏目为准。\n\n约200字简介：\n'+intro200+'\n\n约500字简介：\n'+intro500+'\n\n运行条件：完整解压，Chrome/Edge双击01_作品及成果文件/八十八个地名/index.html，离线体验，无需安装或服务器。建议桌面1920×1080。史料外链需联网。\n\nAI使用：已使用。Codex/GPT-6系列辅助检索、文案、代码、材料及自动化测试；OpenAI内置image_gen生成4张场景图。当前无已确认学生改写、实拍、真人配音、后期和用户测试，详见AI使用补充说明。不要直接把待办写成完成。\n\n团队/学校/指导教师/作品编号：由真实报名人按系统填写，评审版不写入身份信息。\n'
(UPLOAD/'系统填报文案.txt').write_text(systemtxt,encoding='utf-8')
video=[('00:00–00:05','片头：作品名，纸底竹竿。','八十八个地名，一根竹竿上的淮海支前路。'),('00:05–00:35','真实开始页→史料S01/S02；不用实拍占位。','我们以报道中的唐和恩支前竹竿为线索，做一部可离线打开的交互网页。作品选用一篇报道列举的十个名称；它们不是完整清单，也不能推出整段路线。八十八个地名的说法标明另一个报道出处。'),('00:35–01:05','刻与装车；画面标AI艺术示意。','按住竹竿，地名逐步出现。松开时保留进度，也可以用按钮和键盘操作。每一个动作都保留继续和跳过，使阅读不被操作难度挡住。'),('01:05–01:40','推行五节点→一起推两次。','推行时，选定名称依次点亮。泥坡上的共同用力呈现支前的集体性；人物是无名艺术群像，不替真实历史人物安排对白或心理。'),('01:40–02:10','侧光名称→史料层。','侧光是阅读交互。名称来自报道，画面不假装还原文物刻痕。我们公开证据的边界，保留来源差异；不能把没有查到的资料说成原件已无法辨认。'),('02:10–02:40','543点完整出现→来源S04。','一个点表示一万人次，五百四十三个点对应五百四十三万人次。这是统计量的比例表达，不是一份独立个人名单。数字和引语都有来源入口。'),('02:40–03:10','海报输入→生成→下载。','最后写下今天的地名，在本地生成致敬海报。第八十九个地名属于当代创作，不增补历史文物。输入不上传，不排名，不计分。'),('03:10–03:40','代码结构简图、离线文件夹及关于页。','工程采用本地网页，文案、来源与素材分开维护。四张木刻图有显式AI标签和元数据。海报在本地绘制，减少网络和安装依赖。'),('03:40–04:15','关于页、AI说明、QA范围；无伪录音现场。','需要如实说明，当前是AI生成审核版。本轮文字、图片、代码、文档和自动化检查由AI代理完成。团队尚未完成人工史料核验、实拍、真人配音、后期与用户测试；这些必须完成后再据实更新，不能当作已有学生贡献。'),('04:15–04:40','真实海报与来源总表收束。','作品拟用于课堂导入与纪念场馆延伸阅读，应用效果仍待验证。我们希望留下可追溯的出处，也留下愿意继续理解和记住普通人付出的心意。')]
v='作品评审视频脚本 / 总时长4分40秒，片头5秒\n状态：待团队真人录制解说。逐句字幕与解说相同；无真人解说的机器审核录屏不能冒称完成此脚本。\n画面主体必须是当前工程真实运行，不演示尚未实现功能。若团队完成新工作，第3分40秒段按证据改写后重录。\n\n'
for t,shot,n in video: v+=t+'\n画面：'+shot+'\n旁白／字幕：'+n+'\n\n'
(UPLOAD/'作品评审视频脚本.txt').write_text(v,encoding='utf-8')
slides=[('01 / 一根竹竿上的支前路','作品名、离线交互网页、AI审核版状态','真实开始页'),('02 / 从证据出发','S01选定10名称；S02的88；并非完整路线','史料层真实截图'),('03 / 九段结构','序+七幕+尾；目标440秒；快览约3分钟','场景导航截图'),('04 / 刻与推','按住保留进度；节点阅读；键盘与点击替代','刻、推真实截图'),('05 / 一起推与读','集体协力；侧光阅读；不复原伪刻痕','协力、侧光截图'),('06 / 543点','每点1万人次；543万人次；保留统计口径','543点截图与S04来源'),('07 / 第89个地名','当代致敬创作；本地海报；不上传输入','真实海报'),('08 / 实现','原生HTML/CSS/JS；内容来源分离；file://','项目结构简图'),('09 / 来源与AI边界','四图AI艺术示意；文案/代码AI；来源可查','关于页截图'),('10 / 完成与缺口','AI产出与机器QA；无团队人工核验/实拍/配音/后期；用户测试未开展','自检真实条目'),('11 / 接手与价值','完成真实学生工作；课堂/场馆应用待验证；不宣称首创或成效','接手清单'),('12 / 致敬与来源','记住普通人的付出；展示来源入口','尾声真实截图')]
ppt='作品汇报PPT逐页内容 / 12页文本提纲，本轮未生成PPT文件\n团队应据实际状态改定，所有截图来自最终真实运行。\n\n'+'\n\n'.join(a+'\n要点：'+b+'\n配图建议：'+c for a,b,c in slides)
(UPLOAD/'PPT逐页内容.txt').write_text(ppt,encoding='utf-8')
display='作品展示视频分镜 / 目标2分45秒，纯体验审核录屏\n00:00–00:10 开始页；00:10–00:30 刻；00:30–00:40 出发；00:40–01:00 推；01:00–01:20 一起推；01:20–01:45 读；01:45–02:05 数；02:05–02:15 文物留白；02:15–02:40 海报；02:40–02:45 尾声。\n仅使用实际网页录制；未有真人音轨，画面字幕可保留。若实际自动快览约3分钟，以真实录屏时长注明，不伪造计时。\n'
(PACK/'05_补充成果材料'/'作品展示视频分镜.txt').write_text(display,encoding='utf-8')
(PACK/'05_补充成果材料'/'截图与匿名化清单.txt').write_text('截图≤10张，均来自实际运行：开始页、刻、推、一起推、读、543点、海报表单、实际海报、史料层、关于页。\n各图应能证明相应功能；未完成的实拍不用AI图冒充。\n匿名化：无学校/学生/教师姓名、账号头像、桌面通知、浏览器私人标签、路径用户名；PDF作者空；图片无GPS/设备个人标识。报名实名材料单独依法按系统填写。\n用户测试：未开展。不得补造人数、姓名、原话、时间或满意率。可在真实测试后记录：日期/匿名参与者/设备/任务/实际困难/原话/修复版本。\n',encoding='utf-8')
(RECORD/'documents-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
